mapper.select:
SELECT DISTINCT c.card_id FROM card c LEFT JOIN card_company cc ON c.company_id = cc.company_id LEFT JOIN benefit b ON c.card_id = b.card_id LEFT JOIN benefit_category bc ON b.benefit_id = bc.benefit_id LEFT JOIN category ca ON ca.category_id = bc.category_id
ORDER BY c.card_id
LIMIT #{options.limit} OFFSET #{options.page}

SELECT cc.company_id as cc_company_id, cc.company_name as cc_company_name, c.card_id as c_card_id, c.company_id as c_company_id, c.card_name as c_card_name, c.card_type as c_card_type, c.card_image_url as c_card_image_url, c.card_issue_url as c_card_issue_url, c.annual_fee as c_annual_fee, c.prev_month_spending as c_prev_month_spending, b.benefit_id as b_benefit_id, b.card_id as b_card_id, b.benefit_title as b_benefit_title, b.benefit_summary as b_benefit_summary, b.benefit_description as b_benefit_description, b.benefit_icon_url as b_benefit_icon_url, bp.benefit_partner_id as bp_benefit_partner_id, bp.benefit_id as bp_benefit_id, bp.partner_id as bp_partner_id, bc.benefit_category_id as bc_benefit_category_id, bc.benefit_id as bc_benefit_id, bc.category_id as bc_category_id, ca.category_id as ca_category_id,ca.category_name as ca_category_name, ca.category_image_url as ca_category_image_url FROM card c LEFT JOIN card_company cc ON c.company_id = cc.company_id LEFT JOIN benefit b ON c.card_id = b.card_id LEFT JOIN benefit_partner bp ON b.benefit_id = bp.benefit_id LEFT JOIN benefit_category bc ON b.benefit_id = bc.benefit_id LEFT JOIN category ca ON ca.category_id = bc.category_id WHERE c.card_id IN
#{cardId}
ORDER BY c.card_id, b.benefit_id, bc.benefit_category_id, bp.benefit_partner_id
